// v24.xx (feat0h1), HIS MODE DESIGN (2026-10-12): "CAREER - Arcade mode but with the Undercroft ... 10 minute raids ... has all the
// other career/undercroft features we've already created", and his rule "GAMEPLAY ELEMENTS ... SHOULD BE EXACTLY THE SAME IN DEMO AND
// CAREER". A CAREER RAID. Every raid he takes up from the Undercroft (not the DEMO, not the bot) now runs on the DEMO clock: 10
// minutes (it was 9), and the rings never close early, so the clock and the burn at 0 are the pressure, as in the DEMO. The raid
// carries G.career and its own score store G.cs, which the kill score, the waves and the payout build on. His own kit from the stash,
// full enemy damage and coming back empty after a death are the career rules and stay. Nothing is drawn from the seeded stream, so
// a seed builds the same raid, and a co-op partner builds the same one in startRaid. CAREER_ON 0 gives the old raid (the test fixture
// pins it, as it pins GO_SEC).
var CAREER_ON=1, CAREER_RAID_SEC=600;
function careerPostBuild(g){
  if(!g||g.sim||g.arcade) return false;
  var i;
  g.career=1; g.raidLen=g.timeLeft=CAREER_RAID_SEC;
  for(i=0;i<(g.zones||[]).length;i++) g.zones[i].closeAt=undefined;
  g.cs={s:0,k:0,streak:null,waveT:0,waveN:0};
  return true;
}
// Run from startRaid right after the build, in every window that builds the arcade raid

check:
{v:'VER',what:'his mode design (2026-10-12): a raid from the Undercroft is a CAREER raid, the DEMO clock of 10 minutes, no ring closes early, G.career with its own score store, the same seeded raid; CAREER_ON 0 gives the old raid',
 run:function(){
   if(!(window.__deploy&&window.__state&&window.__runPrep&&window.__endRaid)) return 'SKIP: this fixture cannot deploy';
   var bad=[], g, c0=(typeof CAREER_ON==='number')?CAREER_ON:0, i, n=0, e1=-1, k1=-1, rl0=-1;
   try{
     __topClear(); __runPrep();
     CAREER_ON=0;
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||g.over) return 'SKIP: no live raid';
     if(g.career) bad.push('CAREER_ON 0 still built a CAREER raid');
     e1=g.ents.length; k1=g.containers.length; rl0=g.raidLen;
     __endRaid('abandon'); __topClear(); __runPrep();
     CAREER_ON=1;
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||g.over) return bad.concat(['SKIP: no second raid']).join('; ');
     if(g.career!==1) bad.push('a raid from the Undercroft is not a CAREER raid (career '+g.career+')');
     if(g.raidLen!==600||!(g.timeLeft>590)) bad.push('the CAREER clock is '+g.raidLen+' / '+g.timeLeft+', not 10 minutes (the old raid is '+rl0+')');
     for(i=0;i<(g.zones||[]).length;i++) if(g.zones[i].closeAt!==undefined) n++;
     if(n) bad.push(n+' rings still close early in a CAREER raid');
     if(!g.cs||g.cs.s!==0||g.cs.k!==0) bad.push('a CAREER raid has no score store');
     if(g.arcade) bad.push('a CAREER raid is a DEMO raid');
     if(g.ents.length!==e1||g.containers.length!==k1) bad.push('the CAREER raid of seed 4242 differs: ents '+g.ents.length+' vs '+e1+', containers '+g.containers.length+' vs '+k1);
   }catch(x){ bad.push('threw: '+(x&&x.message||x)); }
   finally{ try{ CAREER_ON=c0; }catch(_r){} try{ var g2=__state(); if(g2&&!g2.over) __endRaid('abandon'); }catch(_e){} __topClear(); }
   return bad.length?bad.join('; '):null; }},
